import { GrammarExercise, GrammarExerciseType } from "../types";

export interface ExerciseValidationError {
  field: string;
  message: string;
}

export interface ExerciseValidationResult {
  isValid: boolean;
  errors: ExerciseValidationError[];
}

export interface BatchValidationResult {
  allValid: boolean;
  validExercises: GrammarExercise[];
  invalidExercises: {
    rawIndex: number;
    rawExercise: any;
    errors: ExerciseValidationError[];
  }[];
}

/**
 * Format-specific validator for Grammar exercises generated by AI.
 * Validates strictly against the requirements of each exercise format
 * without altering, guessing, or inserting missing tokens.
 */
export class GrammarExerciseValidator {
  /**
   * Validates a single exercise against its specific format schema.
   */
  static validateExercise(raw: any, targetType: GrammarExerciseType): ExerciseValidationResult {
    const errors: ExerciseValidationError[] = [];

    if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
      return {
        isValid: false,
        errors: [{ field: 'root', message: 'Exercise must be a non-null object' }]
      };
    }

    if (raw.type !== targetType) {
      errors.push({
        field: 'type',
        message: `Expected exercise type '${targetType}', received '${raw.type}'`
      });
    }

    if (typeof raw.explanation !== 'string' || !raw.explanation.trim()) {
      errors.push({
        field: 'explanation',
        message: 'Exercise must include a non-empty explanation string'
      });
    } else if (raw.explanation.length > 500) {
      errors.push({
        field: 'explanation',
        message: 'Explanation must not exceed 500 characters'
      });
    }

    if (!raw.content || typeof raw.content !== 'object' || Array.isArray(raw.content)) {
      errors.push({
        field: 'content',
        message: 'Exercise must include a content object'
      });
      return { isValid: false, errors };
    }

    const { content } = raw;

    switch (targetType) {
      case 'fill-in-the-blank':
        this.validateFillInTheBlank(content, errors);
        break;

      case 'mix-and-match':
        this.validateMixAndMatch(content, errors);
        break;

      case 'choose-correct-sentence':
      case 'multiple-choice':
      case 'true-false':
        this.validateChoiceBased(content, errors, targetType);
        break;

      case 'word-order':
        this.validateWordOrder(content, errors);
        break;

      default:
        errors.push({
          field: 'type',
          message: `Unsupported exercise format: '${targetType}'`
        });
    }

    return {
      isValid: errors.length === 0,
      errors
    };
  }

  /**
   * Validates 'fill-in-the-blank' format.
   * Requires:
   * - sentence: string containing at least one literal '[blank]'
   * - correctAnswers: string[] whose length exactly matches the number of '[blank]'
   * - wordBank: string[] containing all correctAnswers plus distractors (>= 2 items)
   */
  private static validateFillInTheBlank(content: any, errors: ExerciseValidationError[]) {
    if (typeof content.sentence !== 'string' || !content.sentence.trim()) {
      errors.push({
        field: 'content.sentence',
        message: 'Sentence must be a non-empty string'
      });
      return;
    }

    if (content.sentence.length > 300) {
      errors.push({
        field: 'content.sentence',
        message: 'Sentence must not exceed 300 characters'
      });
      return;
    }

    // Check for common malformed placeholders to give precise diagnostic feedback
    const malformedMatches = content.sentence.match(/(___+|\[\.\.\.\]|\(blank\)|\{blank\}|\[BLANK\])/g);
    if (malformedMatches && !content.sentence.includes('[blank]')) {
      errors.push({
        field: 'content.sentence',
        message: `Sentence uses malformed placeholder '${malformedMatches[0]}' instead of literal '[blank]'`
      });
    }

    const blankMatches = content.sentence.match(/\[blank\]/g);
    const blankCount = blankMatches ? blankMatches.length : 0;

    if (blankCount === 0) {
      errors.push({
        field: 'content.sentence',
        message: "Sentence must contain at least one literal '[blank]' placeholder"
      });
    }

    if (!Array.isArray(content.correctAnswers) || content.correctAnswers.length === 0) {
      errors.push({
        field: 'content.correctAnswers',
        message: 'correctAnswers must be a non-empty array of strings'
      });
    } else {
      const hasInvalidItem = content.correctAnswers.some((ans: any) => typeof ans !== 'string' || !ans.trim());
      if (hasInvalidItem) {
        errors.push({
          field: 'content.correctAnswers',
          message: 'All items in correctAnswers must be non-empty strings'
        });
      }

      if (blankCount > 0 && content.correctAnswers.length !== blankCount) {
        errors.push({
          field: 'content.correctAnswers',
          message: `Placeholder count mismatch: sentence has ${blankCount} '[blank]' token(s), but correctAnswers has ${content.correctAnswers.length} item(s)`
        });
      }
    }

    if (!Array.isArray(content.wordBank) || content.wordBank.length < 2) {
      errors.push({
        field: 'content.wordBank',
        message: 'wordBank must be an array of at least 2 strings'
      });
    } else {
      const hasInvalidBankItem = content.wordBank.some((w: any) => typeof w !== 'string' || !w.trim());
      if (hasInvalidBankItem) {
        errors.push({
          field: 'content.wordBank',
          message: 'All items in wordBank must be non-empty strings'
        });
      }

      // Every correctAnswer must be available in wordBank (case-insensitive comparison)
      if (Array.isArray(content.correctAnswers)) {
        const bankNormalized = new Set(content.wordBank.map((w: any) => String(w).trim().toLowerCase()));
        for (const ans of content.correctAnswers) {
          if (typeof ans === 'string' && ans.trim()) {
            if (!bankNormalized.has(ans.trim().toLowerCase())) {
              errors.push({
                field: 'content.wordBank',
                message: `wordBank is missing required answer '${ans}'`
              });
            }
          }
        }
      }
    }
  }

  /**
   * Validates 'mix-and-match' format.
   * Requires:
   * - pairs: array of { id: string, left: string, right: string } (>= 2 pairs, unique IDs)
   */
  private static validateMixAndMatch(content: any, errors: ExerciseValidationError[]) {
    if (!Array.isArray(content.pairs) || content.pairs.length < 2) {
      errors.push({
        field: 'content.pairs',
        message: 'pairs must be an array of at least 2 matching items'
      });
      return;
    }

    const seenIds = new Set<string>();
    const seenLefts = new Set<string>();
    const seenRights = new Set<string>();

    content.pairs.forEach((pair: any, idx: number) => {
      if (!pair || typeof pair !== 'object') {
        errors.push({
          field: `content.pairs[${idx}]`,
          message: 'Pair must be an object with id, left, and right'
        });
        return;
      }

      if (typeof pair.id !== 'string' || !pair.id.trim()) {
        errors.push({
          field: `content.pairs[${idx}].id`,
          message: 'Pair id must be a non-empty string'
        });
      } else if (seenIds.has(pair.id.trim())) {
        errors.push({
          field: `content.pairs[${idx}].id`,
          message: `Duplicate pair id: '${pair.id}'`
        });
      } else {
        seenIds.add(pair.id.trim());
      }

      if (typeof pair.left !== 'string' || !pair.left.trim()) {
        errors.push({
          field: `content.pairs[${idx}].left`,
          message: 'Pair left text must be a non-empty string'
        });
      } else if (seenLefts.has(pair.left.trim().toLowerCase())) {
        errors.push({
          field: `content.pairs[${idx}].left`,
          message: `Duplicate pair left value: '${pair.left}'`
        });
      } else {
        seenLefts.add(pair.left.trim().toLowerCase());
      }

      if (typeof pair.right !== 'string' || !pair.right.trim()) {
        errors.push({
          field: `content.pairs[${idx}].right`,
          message: 'Pair right text must be a non-empty string'
        });
      } else if (seenRights.has(pair.right.trim().toLowerCase())) {
        errors.push({
          field: `content.pairs[${idx}].right`,
          message: `Duplicate pair right value: '${pair.right}'`
        });
      } else {
        seenRights.add(pair.right.trim().toLowerCase());
      }
    });
  }

  /**
   * Validates choice-based formats ('choose-correct-sentence', 'multiple-choice', 'true-false').
   * Requires:
   * - question: non-empty string
   * - options: array of >= 2 non-empty strings
   * - correctAnswerIndex: 0-based integer within bounds
   */
  private static validateChoiceBased(content: any, errors: ExerciseValidationError[], type: string) {
    if (typeof content.question !== 'string' || !content.question.trim()) {
      errors.push({
        field: 'content.question',
        message: 'Question prompt must be a non-empty string'
      });
    }

    if (!Array.isArray(content.options) || content.options.length < 2) {
      errors.push({
        field: 'content.options',
        message: 'options must be an array of at least 2 choices'
      });
      return;
    }

    const hasInvalidOption = content.options.some((opt: any) => typeof opt !== 'string' || !opt.trim());
    if (hasInvalidOption) {
      errors.push({
        field: 'content.options',
        message: 'All options must be non-empty strings'
      });
    }

    if (
      typeof content.correctAnswerIndex !== 'number' ||
      !Number.isInteger(content.correctAnswerIndex)
    ) {
      errors.push({
        field: 'content.correctAnswerIndex',
        message: 'correctAnswerIndex must be an integer'
      });
    } else if (content.correctAnswerIndex < 0 || content.correctAnswerIndex >= content.options.length) {
      errors.push({
        field: 'content.correctAnswerIndex',
        message: `correctAnswerIndex (${content.correctAnswerIndex}) is out of range [0, ${content.options.length - 1}]`
      });
    }
  }

  /**
   * Validates 'word-order' format.
   * Requires:
   * - question: non-empty string (source translation prompt)
   * - correctAnswers: string[] representing individual words in correct order (>= 2 words)
   * - shuffledWords: string[] matching the exact same words in correctAnswers (permutation)
   */
  private static validateWordOrder(content: any, errors: ExerciseValidationError[]) {
    if (typeof content.question !== 'string' || !content.question.trim()) {
      errors.push({
        field: 'content.question',
        message: 'Question prompt must be a non-empty string'
      });
    }

    if (!Array.isArray(content.correctAnswers) || content.correctAnswers.length < 2) {
      errors.push({
        field: 'content.correctAnswers',
        message: 'correctAnswers must be an array of at least 2 individual words'
      });
    } else {
      const hasInvalidAnswer = content.correctAnswers.some((w: any) => typeof w !== 'string' || !w.trim());
      if (hasInvalidAnswer) {
        errors.push({
          field: 'content.correctAnswers',
          message: 'All items in correctAnswers must be non-empty words'
        });
      }
    }

    if (!Array.isArray(content.shuffledWords) || content.shuffledWords.length < 2) {
      errors.push({
        field: 'content.shuffledWords',
        message: 'shuffledWords must be an array of at least 2 individual words'
      });
    } else {
      const hasInvalidShuffled = content.shuffledWords.some((w: any) => typeof w !== 'string' || !w.trim());
      if (hasInvalidShuffled) {
        errors.push({
          field: 'content.shuffledWords',
          message: 'All items in shuffledWords must be non-empty words'
        });
      }
    }

    // Verify multi-set equality between shuffledWords and correctAnswers
    if (Array.isArray(content.correctAnswers) && Array.isArray(content.shuffledWords)) {
      if (content.correctAnswers.length !== content.shuffledWords.length) {
        errors.push({
          field: 'content.shuffledWords',
          message: `Word count mismatch: correctAnswers has ${content.correctAnswers.length} words, shuffledWords has ${content.shuffledWords.length}`
        });
      } else {
        const normalizeWords = (arr: any[]) =>
          arr.map((w: any) => String(w).trim().toLowerCase()).sort();
        const sortedAnswers = normalizeWords(content.correctAnswers);
        const sortedShuffled = normalizeWords(content.shuffledWords);
        const isPermutation = sortedAnswers.every((w, i) => w === sortedShuffled[i]);

        if (!isPermutation) {
          errors.push({
            field: 'content.shuffledWords',
            message: 'shuffledWords must contain the exact same words as correctAnswers'
          });
        }
      }
    }
  }

  /**
   * Sanitizes vocabularyHints dictionary without guessing or mutating answers.
   */
  static cleanVocabularyHints(hints: any): Record<string, string> {
    if (!hints) return {};
    if (Array.isArray(hints)) {
      return hints.reduce((acc: Record<string, string>, curr: any) => {
        if (curr && typeof curr === 'object' && curr.word && curr.translation) {
          acc[String(curr.word).trim()] = String(curr.translation).trim();
        }
        return acc;
      }, {});
    }
    if (typeof hints === 'object') {
      const res: Record<string, string> = {};
      for (const [k, v] of Object.entries(hints)) {
        if (k && v && typeof v === 'string') {
          res[k.trim()] = v.trim();
        }
      }
      return res;
    }
    return {};
  }

  /**
   * Validates a batch of raw exercises.
   * Separates valid exercises from invalid ones for targeted regeneration.
   */
  static validateBatch(
    rawExercises: any[],
    targetType: GrammarExerciseType,
    topicId: string,
    idPrefix: string
  ): BatchValidationResult {
    const validExercises: GrammarExercise[] = [];
    const invalidExercises: {
      rawIndex: number;
      rawExercise: any;
      errors: ExerciseValidationError[];
    }[] = [];

    if (!Array.isArray(rawExercises)) {
      return {
        allValid: false,
        validExercises: [],
        invalidExercises: [{
          rawIndex: -1,
          rawExercise: rawExercises,
          errors: [{ field: 'exercises', message: 'Exercises must be an array' }]
        }]
      };
    }

    rawExercises.forEach((raw, idx) => {
      const result = this.validateExercise(raw, targetType);
      if (result.isValid) {
        const exercise: GrammarExercise = {
          id: `${idPrefix}-ex-${validExercises.length}`,
          topicId,
          type: targetType,
          content: raw.content,
          vocabularyHints: this.cleanVocabularyHints(raw.vocabularyHints),
          explanation: String(raw.explanation).trim(),
          isCompleted: false
        };
        validExercises.push(exercise);
      } else {
        invalidExercises.push({
          rawIndex: idx,
          rawExercise: raw,
          errors: result.errors
        });
      }
    });

    return {
      allValid: invalidExercises.length === 0,
      validExercises,
      invalidExercises
    };
  }
}
